int reachableCount_7(const vector<vector<int>>& adj, int src) { int V = adj.size(), cnt = 0; vector<bool> seen(V, false); queue<int> q; seen[src] = true; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); ++cnt; for (int v2 : adj[u]) if (!seen[v2]) { seen[v2] = true; q.push(v2); } } return cnt; }
bool hasPathBfs_7(const vector<vector<int>>& adj, int src, int dst) { int V = adj.size(); vector<bool> seen(V, false); queue<int> q; seen[src] = true; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); if (u == dst) return true; for (int v2 : adj[u]) if (!seen[v2]) { seen[v2] = true; q.push(v2); } } return false; }
int countComponents_7(const vector<vector<int>>& adj) { int V = adj.size(), comps = 0; vector<bool> seen(V, false); for (int s = 0; s < V; ++s) { if (seen[s]) continue; ++comps; queue<int> q; seen[s] = true; q.push(s); while (!q.empty()) { int u = q.front(); q.pop(); for (int v2 : adj[u]) if (!seen[v2]) { seen[v2] = true; q.push(v2); } } } return comps; }
long long sumDistancesBfs_7(const vector<vector<int>>& adj, int src) { int V = adj.size(); vector<long long> dist(V, -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); for (int v2 : adj[u]) if (dist[v2] == -1) { dist[v2] = dist[u] + 1; q.push(v2); } } long long total = 0; for (int i = 0; i < V; ++i) total += dist[i]; return total; }
int farthestNodeBfs_7(const vector<vector<int>>& adj, int src) { int V = adj.size(); vector<int> dist(V, -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); for (int v2 : adj[u]) if (dist[v2] == -1) { dist[v2] = dist[u] + 1; q.push(v2); } } int best = src, mx = 0; for (int i = 0; i < V; ++i) if (dist[i] > mx) { mx = dist[i]; best = i; } return best; }
long long degreeSum_7(const vector<vector<int>>& adj) { long long s = 0; for (int u = 0; u < (int)adj.size(); ++u) s += adj[u].size(); return s; }
vector<int> topoKahn_7(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> indeg(V, 0); for (int u = 0; u < V; ++u) for (int v2 : adj[u]) ++indeg[v2]; queue<int> q; for (int u = 0; u < V; ++u) if (indeg[u] == 0) q.push(u); vector<int> order; while (!q.empty()) { int u = q.front(); q.pop(); order.push_back(u); for (int v2 : adj[u]) { --indeg[v2]; if (indeg[v2] == 0) q.push(v2); } } return order; }
